<?php

namespace Stanford\LectureEvaluation;

/**
 * Strict validation for everything that reaches a REDCap query from a request or from data.
 *
 * Nothing here escapes: a value that does not match its pattern is rejected, never cleaned. Queries
 * are parameterized as well; validation is what keeps junk (and lookups for it) out entirely.
 *
 * It has no REDCap dependencies so it can be unit tested on its own (tests/unit).
 */
final class Validator
{
    /**
     * Student hashes are generated by generateRandomHash(8, false, true, false): 8 characters from
     * 34789ACDEFHJKLMNPRTWXY. The pattern is wider than that (any letters/digits, 6-40) so that hashes
     * set by hand or by an older generator still work, but it can never contain a quote, bracket,
     * space or operator.
     */
    const HASH_PATTERN = '/^[A-Za-z0-9]{6,40}$/';

    /** Record names this module creates or links to: L.., S.., E<n>. Letters, digits, _ - . only. */
    const RECORD_ID_PATTERN = '/^[A-Za-z0-9_.\-]{1,100}$/';

    /** Raw checkbox codes, e.g. 2026, 2021_1_1, 2019-1-1. */
    const CHECKBOX_CODE_PATTERN = '/^[A-Za-z0-9_.\-]{1,100}$/';

    /**
     * @param mixed $value
     * @return string|null the hash, or null when it is missing or malformed
     */
    public static function hash($value)
    {
        return (is_string($value) && preg_match(self::HASH_PATTERN, $value)) ? $value : null;
    }

    /**
     * @param mixed $value
     * @return string|null the record name, or null when it is missing or malformed
     */
    public static function recordId($value)
    {
        if (is_int($value)) {
            $value = (string)$value;
        }
        return (is_string($value) && preg_match(self::RECORD_ID_PATTERN, $value)) ? $value : null;
    }

    /**
     * @param mixed $value
     * @return int|null the project id, or null when it is not a positive integer
     */
    public static function pid($value)
    {
        if (is_int($value)) {
            return $value > 0 ? $value : null;
        }
        return (is_string($value) && preg_match('/^[1-9][0-9]{0,9}$/', $value)) ? (int)$value : null;
    }
}
